// Un mensaje por notificación: emails esperan "Enviar"; los canales manuales traen el bloque listo para pegar.
const out = [];
$input.all().forEach((it, i) => {
  const n = it.json;
  if (!n.chat_id) return;
  const manual = n.status === 'pendente_manual';
  const cuerpo = String(n.corpo || '');
  const recorte = cuerpo.length > 2600 ? cuerpo.slice(0, 2600) + '\n[...recortado, completo en la tabla notificacoes]' : cuerpo;
  const cab = manual
    ? `<b>📋 Para enviar a mano #${n.id}</b> · ${esc(n.canal)} · ${n.n_urls} URL(s)${n.nivel > 0 ? ' · ESCALADO' : ''}`
    : `<b>✉️ Email para aprobar #${n.id}</b> · ${esc(n.canal)} · ${n.n_urls} URL(s)${n.nivel > 0 ? ' · ESCALADO' : ''}`;
  const lineas = [
    cab,
    n.destinatario ? `Para: ${esc(n.destinatario)}` : null,
    n.asunto ? `Asunto: ${esc(n.asunto)}` : null,
    !manual && n.dry_run !== 'false' ? '🧪 <b>DRY RUN activo:</b> aunque aprietes Enviar, el email NO sale hasta poner dry_run=false en la tabla config.' : null,
    '',
    `<pre>${esc(recorte)}</pre>`,
  ].filter((x) => x !== null);
  out.push({
    json: {
      id: n.id,
      chat_id: String(n.chat_id),
      texto: lineas.join('\n').slice(0, 4000),
      b1_text: manual ? '✅ Marcar enviada' : '📤 Enviar', b1_data: manual ? `em:${n.id}` : `se:${n.id}`,
      b2_text: '🚫 Cancelar', b2_data: `cn:${n.id}`,
    },
    pairedItem: { item: i },
  });
});
return out;

// Entrada: fila con el admin id (config) tras el Telegram Trigger de callback_query.
const cq = ($('Telegram Trigger').first().json || {}).callback_query;
const admin = String(($input.first().json || {}).valor || '').trim();
if (!cq) return [];
const base = { query_id: cq.id, chat_id: cq.message && cq.message.chat && cq.message.chat.id, message_id: cq.message && cq.message.message_id };
const m = String(cq.data || '').match(/^(ap|re|se|cn|em):(\d+)$/);
const autorizado = admin !== '' && String(cq.from && cq.from.id) === admin;
if (!autorizado || !m) {
  return [{ json: { ...base, ok: false, answer_text: autorizado ? 'Acción no reconocida' : 'No autorizado' } }];
}
return [{ json: { ...base, ok: true, accion: m[1], id: Number(m[2]), texto_original: (cq.message && cq.message.text) || '' } }];

// Entrada: resultado del UPDATE (achados / notifs afectados). Arma la respuesta al botón y el texto nuevo del mensaje.
const cb = $('Parsear callback').first().json;
const r = $input.first().json || {};
const hecho = Number(r.achados || 0) + Number(r.notifs || 0) > 0;
const ETIQUETA = {
  ap: '✅ APROBADO', re: '❌ RECHAZADO', se: '📤 APROBADO PARA ENVIAR', cn: '🚫 CANCELADO', em: '✅ MARCADA COMO ENVIADA',
};
const etiqueta = hecho ? ETIQUETA[cb.accion] : '↩️ YA PROCESADO ANTES';
return [{
  json: {
    query_id: cb.query_id,
    chat_id: cb.chat_id,
    message_id: cb.message_id,
    answer_text: hecho ? 'Listo' : 'Ya estaba procesado',
    nuevo_texto: `${etiqueta} (#${cb.id})\n\n${cb.texto_original}`.slice(0, 4000),
  },
}];
